/// Opaque parsed network handle. Carries the parsed [`BalancedNetwork`], the
/// [`IndexCore`] derived from it once at parse time (so every indexed query
/// reuses the same bus-id map and per-bus aggregates instead of rebuilding
/// them), and the reader's fidelity warnings ([`pio_warnings`]).
pub struct PioNetwork {
    net: BalancedNetwork,
    core: IndexCore,
    /// The reader's findings as structured records.
    diagnostics: Vec<StructuredDiagnostic>,
    /// The same findings as `CODE: message` lines.
    warnings: Vec<String>,
}

// The handle is immutable after construction and the C ABI documents concurrent
// reads from any number of threads as safe (see the cbindgen header preamble).
// That guarantee requires `PioNetwork: Send + Sync`; pin it at compile time so
// a future field that is not `Sync` fails the build instead of weakening it.
const _: fn() = || {
    fn assert_send_sync<T: Send + Sync>() {}
    assert_send_sync::<PioNetwork>();
};

/// Copy `msg` (truncated to fit) into a caller `char[len]` buffer, always
/// NUL-terminated. Truncation backs up to a UTF-8 character boundary so a
/// clipped message is still valid UTF-8. Shared by the error and warning
/// outputs.
///
/// # Safety
/// A non-NULL `buf` must point to at least `len` writable bytes; the write
/// stays within `len` (at most `len - 1` message bytes plus the terminating
/// NUL). NULL or `len == 0` is a no-op.
unsafe fn copy_to_buf(buf: *mut c_char, len: usize, msg: &str) {
    unsafe {
        if buf.is_null() || len == 0 {
            return;
        }
        let bytes = msg.as_bytes();
        let mut n = bytes.len().min(len - 1);
        while n > 0 && !msg.is_char_boundary(n) {
            n -= 1;
        }
        std::ptr::copy_nonoverlapping(bytes.as_ptr().cast::<c_char>(), buf, n);
        *buf.add(n) = 0;
    }
}

unsafe fn cstr<'a>(p: *const c_char) -> Option<&'a str> {
    unsafe {
        if p.is_null() {
            return None;
        }
        CStr::from_ptr(p).to_str().ok()
    }
}

/// Move `s` into an owned C string, or `None` if it holds an interior NUL byte
/// (which can't cross as a C string). Callers return the `None` as a real error
/// rather than silently handing back an empty string.
fn into_cstring(s: String) -> Option<*mut c_char> {
    CString::new(s).ok().map(CString::into_raw)
}

/// Finish a `*mut c_char` entry point: hand back the owned C string, or on an
/// interior NUL write the error into `errbuf` (NULL/0 to skip) and return NULL.
/// The shared tail of the string-returning functions.
fn finish_cstring(s: String, errbuf: *mut c_char, errlen: usize) -> *mut c_char {
    match into_cstring(s) {
        Some(p) => p,
        None => {
            unsafe {
                let msg = coded(
                    &codes::BIND_CAPI_INTERIOR_NUL,
                    "output contained an interior NUL byte",
                );
                copy_to_buf(errbuf, errlen, &msg);
            };
            std::ptr::null_mut()
        }
    }
}

/// Finish a `*mut c_char` entry point: run `f` (the string payload or an error
/// message) under the panic guard and hand back an owned C string, or write
/// the error (`panic_msg` if `f` panicked) into `errbuf` and return NULL. The
/// shared tail of the string-returning functions that carry no warning buffer.
/// Used by the always built `pio_to_json` as well as the dist and pkg
/// entry points, so it carries no feature gate.
unsafe fn finish_string(
    errbuf: *mut c_char,
    errlen: usize,
    panic_msg: &str,
    f: impl FnOnce() -> Result<String, String>,
) -> *mut c_char {
    unsafe {
        match catch_unwind(AssertUnwindSafe(f)) {
            Ok(Ok(text)) => finish_cstring(text, errbuf, errlen),
            Ok(Err(msg)) => {
                copy_to_buf(errbuf, errlen, &msg);
                std::ptr::null_mut()
            }
            Err(_) => {
                copy_to_buf(errbuf, errlen, &coded(&codes::BIND_CAPI_PANIC, panic_msg));
                std::ptr::null_mut()
            }
        }
    }
}

/// Run `f` at the FFI boundary, catching any panic so it can't unwind across
/// `extern "C"` (UB). Returns `fallback` if `f` panics.
unsafe fn guard<R>(fallback: R, f: impl FnOnce() -> R) -> R {
    catch_unwind(AssertUnwindSafe(f)).unwrap_or(fallback)
}

/// Box a `BalancedNetwork` into an owned network handle, building its [`IndexCore`] once so
/// every indexed query reuses it. The one constructor for `*mut PioNetwork`.
fn make_network(net: BalancedNetwork, diagnostics: Vec<StructuredDiagnostic>) -> *mut PioNetwork {
    let core = IndexCore::build(&net);
    Box::into_raw(Box::new(PioNetwork {
        core,
        warnings: powerio::diagnostics::render_lines(&diagnostics),
        diagnostics,
        net,
    }))
}

/// Finish a `*mut PioNetwork` entry point: run `f` (producing a `BalancedNetwork` with
/// its read findings, or an error message) under the panic guard, hand back an
/// owned handle, or write the error, `panic_msg` if `f` panicked, into `errbuf`
/// and return NULL. The shared tail of every handle-returning function
/// (`pio_parse_file`, `pio_parse_str`, `pio_read_dir`, `pio_normalize`).
unsafe fn finish_network(
    errbuf: *mut c_char,
    errlen: usize,
    panic_msg: &str,
    f: impl FnOnce() -> Result<(BalancedNetwork, Vec<StructuredDiagnostic>), String>,
) -> *mut PioNetwork {
    unsafe {
        // make_network runs inside the guard: IndexCore::build is part of the
        // entry point's work and the header promises panics never cross the
        // boundary.
        match catch_unwind(AssertUnwindSafe(|| {
            f().map(|(net, diagnostics)| make_network(net, diagnostics))
        })) {
            Ok(Ok(handle)) => handle,
            Ok(Err(msg)) => {
                copy_to_buf(errbuf, errlen, &msg);
                std::ptr::null_mut()
            }
            Err(_) => {
                copy_to_buf(errbuf, errlen, &coded(&codes::BIND_CAPI_PANIC, panic_msg));
                std::ptr::null_mut()
            }
        }
    }
}

/// ABI version of this C interface. Bump on any breaking change to an existing
/// `pio_*` signature or documented behavior, including removing a supported
/// format token from the C API. New additive symbols do not require a bump.
/// A consumer compares [`pio_abi_version`] against the value it was built
/// against (the `PIO_ABI_VERSION` macro in `powerio.h`) and refuses a
/// mismatched library before calling another function.
///
/// New data uses new symbols or versioned Arrow, `.pio.json`, or format
/// specific JSON schemas. Existing signatures do not change without an ABI
/// version increment.
///
/// 5 is the current version. It bumped because every ABI visible JSON document
/// changed shape: `pio_schema_versions_json` dropped four keys,
/// `pio_dist_capabilities_json` renamed `schema_version` to `powerio_version`,
/// and the Arrow metadata key became `powerio.version`. A binding built against
/// 4 would pass a handshake it should fail and read `null` for keys it mirrors.
/// The same bump carries the diagnostic grammar: every errbuf message and
/// warning line reads `CODE: message`, and the seven conversion entry points
/// publish structured records through `out_diagnostics_json` in place of the
/// text `out_warnings` channel.
pub const PIO_ABI_VERSION: u32 = 5;

/// Frozen at 1 and no longer meaningful. It existed to absorb distribution
/// volatility, but that volatility lives in the BMOPF schema, which changes a
/// reader, a writer and an emitted token, and no C signature. One shared object
/// carrying two compatibility promises is a thing no mature C library does.
///
/// The symbol stays because PowerIO.jl gates twelve distribution call sites on
/// resolving it, and removing it would break every distribution call on a
/// library that fully supports distribution. Foreign schema drift is reported at
/// runtime by [`pio_build_info`] instead, which can express "BMOPF 0.2 but not
/// 0.3"; an integer checked once at load cannot.
#[cfg(feature = "dist")]
pub const PIO_DIST_ABI_VERSION: u32 = 1;

/// Recommended error buffer size: pass a `char[PIO_ERRBUF_MIN]` to any
/// `errbuf`/`warnbuf` parameter and a message always fits without truncation.
pub const PIO_ERRBUF_MIN: usize = 256;

/// Keep SCOPF document ordinals 0-based.
#[cfg(feature = "prob")]
pub const PIO_SCOPF_INDEX_BASE_ZERO: i32 = 0;

/// Renumber SCOPF document ordinals to 1-based.
#[cfg(feature = "prob")]
pub const PIO_SCOPF_INDEX_BASE_ONE: i32 = 1;

/// The ABI version the library was built with (see [`PIO_ABI_VERSION`]). Lets a
/// consumer detect a stale or incompatible library at load time. Infallible.
#[unsafe(no_mangle)]
pub extern "C" fn pio_abi_version() -> u32 {
    PIO_ABI_VERSION
}

/// The ABI version of the optional `pio_dist_*` C API. Only linked when the
/// `dist` feature is compiled in; probe that first with `pio_has_feature("dist")`
/// if loading dynamically.
#[cfg(feature = "dist")]
#[unsafe(no_mangle)]
pub extern "C" fn pio_dist_abi_version() -> u32 {
    PIO_DIST_ABI_VERSION
}

#[cfg(feature = "dist")]
fn dist_capabilities_json() -> String {
    serde_json::json!({
        "dist": true,
        // This document is powerio's own, so it states the release that wrote
        // it. The BMOPF schema it reports below belongs to the task force, and
        // its version is theirs to set.
        powerio::version::VERSION_KEY: powerio::VERSION,
        "bmopf_fixed_taps": true,
        "bmopf_center_tap_leakage": true,
        "bmopf_delta_wye_leakage": true,
        "bmopf_delta_roll": true,
        "bmopf_voltage_source_merge": true,
        "bmopf_transformer_diagnostics": true,
        // Not a fetch location. Use it together with `bmopf_schema_version`.
        "bmopf_schema_id": powerio_dist::BMOPF_SCHEMA_ID,
        "bmopf_schema_version": powerio_dist::BMOPF_SCHEMA_VERSION,
        "typed_capacitors": true,
        "line_and_generator_ratings": true,
        "per_sequence_bus_bounds": true,
        "transformer_extras_relocation": true,
    })
    .to_string()
}

/// Return distribution capability flags as owned JSON. Free the returned string
/// with [`pio_string_free`]. Only linked when the `dist` feature is compiled in;
/// runtime loaders can either check `pio_has_feature("dist")` or probe for this
/// symbol directly. The JSON schema is versioned separately from
/// [`PIO_DIST_ABI_VERSION`] so new additive flags do not force a C signature
/// change.
#[cfg(feature = "dist")]
#[unsafe(no_mangle)]
pub extern "C" fn pio_dist_capabilities_json() -> *mut c_char {
    // Guarded like every other allocating entry point: `serde_json::json!`
    // expands to `to_value(..).unwrap()`, so the panic-free property would
    // otherwise rest on the current field types alone.
    unsafe {
        guard(std::ptr::null_mut(), || {
            into_cstring(dist_capabilities_json()).unwrap_or(std::ptr::null_mut())
        })
    }
}

/// Report the schema version of each document format in this library, as
/// owned JSON. Free the returned string with [`pio_string_free`]. Infallible.
///
/// [`PIO_ABI_VERSION`] does not cover these versions. A binding that
/// mirrors one of them must read it from here and refuse a library it does
/// not agree with. A key is `null` when the owning feature is not compiled
/// in. Keys are only added over time. `powerio_version` covers every
/// document powerio authors; `bmopf_schema` is the foreign schema this build
/// speaks, whose version belongs to whoever owns it.
#[unsafe(no_mangle)]
pub extern "C" fn pio_schema_versions_json() -> *mut c_char {
    unsafe { guard(std::ptr::null_mut(), schema_versions_json_ptr) }
}

/// The BMOPF schema version this build speaks, or `None` (serialized as
/// `null`) when it cannot speak that format. Both handshake documents read it
/// here so they cannot disagree about it.
fn bmopf_schema_version() -> Option<&'static str> {
    #[cfg(feature = "dist")]
    {
        Some(powerio_dist::BMOPF_SCHEMA_VERSION)
    }
    #[cfg(not(feature = "dist"))]
    {
        None
    }
}

/// The body of [`pio_schema_versions_json`], called inside the panic guard.
fn schema_versions_json_ptr() -> *mut c_char {
    // Every document powerio authors states one version, the release that
    // wrote it, so this report needs one key for all of them. What stays
    // separate is the C handshake integer and any foreign schema this build
    // speaks, whose version belongs to whoever owns that schema.
    let doc = serde_json::json!({
        powerio::version::VERSION_KEY: powerio::VERSION,
        "abi": PIO_ABI_VERSION,
        "bmopf_schema": bmopf_schema_version(),
    });
    into_cstring(doc.to_string()).unwrap_or(std::ptr::null_mut())
}

/// Everything a loader needs to decide what this library can do, as one owned
/// JSON document. Free the returned string with [`pio_string_free`]. Infallible.
///
/// `curl_version_info` is the shape: one call, one report, and new keys arrive
/// without a new symbol. Keys are only added. A caller with no JSON parser
/// keeps using [`pio_has_feature`] and [`pio_abi_version`], which say the same
/// things one answer at a time.
///
/// Every `errbuf` message and every warning line reads `CODE: message`, where
/// the code is a dotted diagnostic identity such as
/// `EMIT.PSSE.FIELD_DROPPED`. `diagnostic_namespaces` lists the first segments
/// powerio emits, so a consumer that merges reports from several producers can
/// tell powerio's findings from its own. `error_categories` lists the coarse
/// projection each fatal code is published under, for a consumer that wants
/// five buckets rather than the full code set. Both sets are stable; a member
/// may be added.
///
/// `json_classes` lists the classification families [`pio_classify_str`]
/// answers with, so a binding that routes a bare `.json` reads the closed set
/// from the library rather than hardcoding it.
#[unsafe(no_mangle)]
pub extern "C" fn pio_build_info() -> *mut c_char {
    unsafe { guard(std::ptr::null_mut(), build_info_ptr) }
}

/// The body of [`pio_build_info`], called inside the panic guard.
fn build_info_ptr() -> *mut c_char {
    let doc = serde_json::json!({
        powerio::version::VERSION_KEY: powerio::VERSION,
        "abi": PIO_ABI_VERSION,
        "features": {
            "arrow": cfg!(feature = "arrow"),
            "matrix": cfg!(feature = "matrix"),
            "gridfm": cfg!(feature = "gridfm"),
            "dist": cfg!(feature = "dist"),
            "pkg": cfg!(feature = "pkg"),
            "prob": cfg!(feature = "prob"),
        },
        // Foreign schemas this build speaks. The version belongs to whoever
        // owns the schema, which is why an integer checked once at load cannot
        // express it.
        "foreign_schemas": { "bmopf": bmopf_schema_version() },
        "error_categories": powerio::ErrorCategory::TOKENS,
        "diagnostic_namespaces": powerio::diagnostics::DiagnosticStage::NAMESPACES,
        "json_classes": powerio::format::routing::JSON_CLASSES,
    });
    into_cstring(doc.to_string()).unwrap_or(std::ptr::null_mut())
}

/// Whether the matrix Arrow table API is usable in this build. Returns 1
/// only when both `arrow` and `matrix` are compiled in. Matrix tables use
/// `pio_to_arrow`. Infallible.
#[unsafe(no_mangle)]
pub extern "C" fn pio_matrix_available() -> i32 {
    i32::from(cfg!(all(feature = "arrow", feature = "matrix")))
}

/// Whether an optional build feature is compiled in: pass `"arrow"`, `"matrix"`,
/// `"gridfm"`, `"dist"`, `"pkg"`, or `"prob"`. Returns 1 if present, 0 otherwise (and 0
/// for a NULL or unknown name). The optional entry points (`pio_to_arrow`, the
/// matrix Arrow tables, the `pio_read_dir`/gridfm path, the `pio_dist_*` block,
/// and the `pio_package_*` block) are only linked when their feature is built,
/// so a consumer that loaded the library at runtime probes for them here
/// instead of resolving symbols blind. Feature names are strings like format
/// names, so a new feature never changes this signature. Infallible.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_has_feature(feature: *const c_char) -> i32 {
    unsafe {
        guard(0, || {
            let Some(name) = cstr(feature) else { return 0 };
            let features: &[(&str, bool)] = &[
                ("arrow", cfg!(feature = "arrow")),
                ("matrix", cfg!(feature = "matrix")),
                ("gridfm", cfg!(feature = "gridfm")),
                ("dist", cfg!(feature = "dist")),
                ("pkg", cfg!(feature = "pkg")),
                ("prob", cfg!(feature = "prob")),
            ];
            i32::from(features.iter().any(|&(n, on)| n == name && on))
        })
    }
}

/// The crate version string (a semver string), `'static` and NUL-terminated. Do
/// NOT free it. Informational; pair it with [`pio_abi_version`] for the actual
/// compatibility check.
#[unsafe(no_mangle)]
pub extern "C" fn pio_version() -> *const c_char {
    // env! is resolved at compile time; the trailing NUL makes it a valid C
    // string and the 'static lifetime means the pointer is always valid and
    // never owned by the caller.
    concat!(env!("CARGO_PKG_VERSION"), "\0")
        .as_ptr()
        .cast::<c_char>()
}

fn target_format_from_c(to: *const c_char) -> Result<TargetFormat, String> {
    let to = required_cstr(to, "to")?;
    to.parse::<TargetFormat>().map_err(err_line)
}

fn optional_cstr<'a>(p: *const c_char, name: &str) -> Result<Option<&'a str>, String> {
    if p.is_null() {
        Ok(None)
    } else {
        unsafe { cstr(p) }.map(Some).ok_or_else(|| {
            coded(
                &codes::BIND_CAPI_INVALID_UTF8,
                format!("{name} is not UTF-8"),
            )
        })
    }
}

/// Like [`cstr`] but a NULL or non-UTF-8 pointer is an error naming the
/// offending parameter. Entry points use this for required strings.
/// Used by the always-built `pio_classify_str` as well as the dist and pkg
/// entry points, so it carries no feature gate.
///
/// The two ways a string argument fails carry different codes: a NULL pointer
/// and bytes that are not UTF-8 are separate mistakes on the caller's side.
fn required_cstr<'a>(p: *const c_char, name: &str) -> Result<&'a str, String> {
    if p.is_null() {
        return Err(coded(
            &codes::BIND_CAPI_NULL_ARGUMENT,
            format!("{name} is NULL"),
        ));
    }
    unsafe { cstr(p) }.ok_or_else(|| {
        coded(
            &codes::BIND_CAPI_INVALID_UTF8,
            format!("{name} is not UTF-8"),
        )
    })
}

/// The message for a NULL handle argument, naming the handle in `what`.
fn null_handle(what: &str) -> String {
    coded(&codes::BIND_CAPI_NULL_HANDLE, format!("{what} is NULL"))
}

/// The errbuf line for a lowering refusal. The pass reports every blocker as a
/// coded record and the C surface carries one message, so take the first
/// record's own line rather than inventing a code for it.
#[cfg(feature = "pkg")]
fn lowering_err_line(e: &powerio_pkg::MulticonductorToBalancedError) -> String {
    e.diagnostics.first().map_or_else(
        || coded(&codes::BIND_CAPI_UNCODED_FAILURE, e),
        powerio::diagnostics::render_line,
    )
}

/// Parse `path` (format from extension, or `from` if non-NULL) into a network
/// handle. `from` accepts the [`pio_parse_str`] format names plus
/// `pypsa-csv`/`pypsa`, `goc3-json`/`goc3`, `surge-json`/`surge`, and `pwb`;
/// that includes `pslf`/`epc`, and `.epc` is inferred by extension. A PyPSA CSV folder is a directory, so it can only
/// enter through this function, with `from = "pypsa-csv"` (or NULL when the
/// directory holds a `network.csv`). Read fidelity warnings attach to the
/// handle ([`pio_warnings`]). Returns `NULL` on error and writes the message
/// into `errbuf`. Free the handle with [`pio_network_free`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_parse_file(
    path: *const c_char,
    from: *const c_char,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut PioNetwork {
    unsafe {
        finish_network(errbuf, errlen, "panic while parsing", || {
            let path = required_cstr(path, "path")?;
            let from = optional_cstr(from, "from")?;
            powerio::parse_file(std::path::Path::new(path), from)
                .map(|p| (p.network, p.diagnostics))
                .map_err(err_line)
        })
    }
}

/// Parse in-memory case `text` of the named `format` into a network handle.
/// Unlike [`pio_parse_file`] there is no path to infer from, so `format` is
/// required: one of `matpower`/`m`, `powermodels`/`pm`, `egret`,
/// `pandapower-json`/`pandapower`/`pp`, `psse`/`raw`, `psse34`, `psse35`,
/// `powerworld`/`aux`, `pslf`/`epc`, `goc3-json`/`goc3`, `surge-json`/`surge`,
/// or `opfdata-json`/`opfdata`. PyPSA CSV folders are
/// directories, not text; parse them with [`pio_parse_file`] and
/// `from = "pypsa-csv"`. Read fidelity warnings attach to the handle
/// ([`pio_warnings`]). Returns `NULL` on error and writes the message into
/// `errbuf`. Free the handle with [`pio_network_free`]. Balanced model JSON is
/// not a case format and has no token here: read it with [`pio_from_json`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_parse_str(
    text: *const c_char,
    format: *const c_char,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut PioNetwork {
    unsafe {
        finish_network(errbuf, errlen, "panic while parsing", || {
            let text = required_cstr(text, "text")?;
            let format = required_cstr(format, "format")?;
            powerio::parse_str(text, format)
                .map(|p| (p.network, p.diagnostics))
                .map_err(err_line)
        })
    }
}

/// Parse `len` bytes of in-memory case data of the named `format` into a
/// network handle. Accepts every [`pio_parse_str`] format name plus `pwb`:
/// PowerWorld binary has no text form, so before this call the only way to
/// reach that reader was [`pio_parse_file`], which means staging a temporary
/// file. `bytes` need not be NUL-terminated and may contain interior NULs;
/// text formats are decoded as UTF-8 and fail with a message if they are not.
///
/// Read fidelity warnings attach to the handle ([`pio_warnings`]). Returns
/// `NULL` on error and writes the message into `errbuf`. Free the handle with
/// [`pio_network_free`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_parse_bytes(
    bytes: *const u8,
    len: usize,
    format: *const c_char,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut PioNetwork {
    unsafe {
        finish_network(errbuf, errlen, "panic while parsing", || {
            let format = required_cstr(format, "format")?;
            // A zero length read is an empty case, and every reader rejects
            // one with its own message; a NULL pointer is a caller bug.
            let slice = if len == 0 {
                &[][..]
            } else if bytes.is_null() {
                return Err(coded(&codes::BIND_CAPI_NULL_ARGUMENT, "bytes is NULL"));
            } else {
                std::slice::from_raw_parts(bytes, len)
            };
            powerio::parse_bytes(slice, format)
                .map(|p| (p.network, p.diagnostics))
                .map_err(err_line)
        })
    }
}

/// Classify in-memory JSON case `text` by its top level markers, without
/// parsing the case. Writes one of
///
/// - `transmission:<format>` (e.g. `transmission:powermodels-json`)
/// - `distribution:<format>` (e.g. `distribution:pmd-json`)
/// - `package` (a `.pio.json` package; read it with the package entry points)
/// - `model-json` (bare balanced model JSON; read it with [`pio_from_json`])
/// - `ambiguous` (strong markers from both domains; pass an explicit format)
/// - `unknown` (no recognized marker, or not a JSON object)
///
/// into the caller `outbuf` (truncated to fit, always NUL-terminated) and
/// returns the total byte length of the classification string (the
/// size-then-fill idiom of [`pio_warnings`]). Returns 0 for NULL `text`. The
/// markers are the same ones the transmission parser's `.json` sniffing uses,
/// so a binding can route a bare `.json` before choosing a parser.
///
/// That list is closed: the family (the label up to the first `:`) is always
/// one of those six, the spellings are permanent, and a new family is an
/// addition with a changelog line. `pio_build_info` reports the same set under
/// `json_classes`, so a binding need not hardcode it.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_classify_str(
    text: *const c_char,
    outbuf: *mut c_char,
    outlen: usize,
) -> usize {
    unsafe {
        // Terminate up front so every early return, including a panic inside
        // the guard, leaves outbuf a valid empty string.
        copy_to_buf(outbuf, outlen, "");
        guard(0, || {
            let Ok(text) = required_cstr(text, "text") else {
                return 0;
            };
            let label = classify_label(text);
            copy_to_buf(outbuf, outlen, &label);
            label.len()
        })
    }
}

/// The label is the classification family, plus `:<format>` for the two
/// classes that detect one. Both halves come from the classifier, so the C
/// vocabulary cannot drift from the Rust one.
fn classify_label(text: &str) -> String {
    use powerio::format::routing::{self, Detection, JsonClass};
    let class = routing::classify_json_text(text);
    match class {
        JsonClass::Case(Detection::Known(format)) => {
            format!("{}:{}", class.family(), format.name())
        }
        _ => class.family().to_string(),
    }
}

/// Serialize `net` to its model JSON: the same object a `.pio.json` package
/// carries under `model.balanced_network`, without the surrounding document.
/// This is the bindings' data transport and the only route to it: model JSON
/// is powerio's own document rather than a case format, so it has no format
/// token. Returns an owned C string (free with [`pio_string_free`]), `NULL` on
/// error.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_to_json(
    net: *const PioNetwork,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut c_char {
    unsafe {
        finish_string(errbuf, errlen, "panic while serializing model JSON", || {
            let net = net.as_ref().ok_or_else(|| null_handle("network handle"))?;
            net.net.to_json().map_err(err_line)
        })
    }
}

/// Parse model JSON produced by [`pio_to_json`] (or lifted from a `.pio.json`
/// document's `model.balanced_network`) back into an owned handle, the inverse
/// of [`pio_to_json`]. A bare `.json` file holding this document classifies as
/// `model-json` through [`pio_classify_str`]. Returns `NULL` on error. Free
/// with [`pio_network_free`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_from_json(
    text: *const c_char,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut PioNetwork {
    unsafe {
        finish_network(errbuf, errlen, "panic while parsing model JSON", || {
            let text = required_cstr(text, "text")?;
            BalancedNetwork::from_json(text)
                .map(|net| (net, Vec::new()))
                .map_err(err_line)
        })
    }
}

/// Read one scenario of a dataset directory in the named `from` format into a
/// network handle. `gridfm` (the
/// gridfm-datakit Parquet layout; `dir` resolves leniently: the `raw/` leaf,
/// a `<case>/` directory with a `raw/` child, or a parent holding exactly one
/// such case) is the currently supported dataset format. `scenario` selects within a
/// multi-scenario dataset ([`pio_scenario_ids`] enumerates them); formats
/// without scenarios take `0`. Read fidelity warnings attach to the handle
/// ([`pio_warnings`]). Returns `NULL` on error and writes the message into
/// `errbuf`. Free the handle with [`pio_network_free`]. Built
/// `--features gridfm`.
#[cfg(feature = "gridfm")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_read_dir(
    dir: *const c_char,
    from: *const c_char,
    scenario: i64,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut PioNetwork {
    unsafe {
        finish_network(errbuf, errlen, "panic while reading dataset", || {
            let dir = required_cstr(dir, "dir")?;
            let from = required_cstr(from, "from")?;
            powerio_matrix::read_dataset_dir(std::path::Path::new(dir), from, scenario)
                .map(|read| (read.network, read.diagnostics))
                .map_err(err_line)
        })
    }
}

/// Write the distinct scenario ids (ascending) of the dataset directory `dir`
/// in the named `from` format into `out`, up to `cap` entries, and return the
/// total count: the cap/count convention of [`pio_bus_ids`]. `gridfm` is the
/// currently supported dataset format. Returns `-1` on error and writes the message into
/// `errbuf` (unlike the handle extractors, this reads the filesystem and can
/// fail). Built `--features gridfm`.
#[cfg(feature = "gridfm")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_scenario_ids(
    dir: *const c_char,
    from: *const c_char,
    out: *mut i64,
    cap: usize,
    errbuf: *mut c_char,
    errlen: usize,
) -> isize {
    unsafe {
        finish_fill(
            errbuf,
            errlen,
            "panic while reading scenario ids",
            out,
            cap,
            || {
                let dir = required_cstr(dir, "dir")?;
                let from = required_cstr(from, "from")?;
                powerio_matrix::dataset_scenario_ids(std::path::Path::new(dir), from)
                    .map_err(err_line)
            },
        )
    }
}

/// The fidelity warnings attached to the handle at construction (by whichever
/// of [`pio_parse_file`], [`pio_parse_str`], `pio_read_dir`, or
/// [`pio_normalize`] built it), `\n`-joined into `warnbuf` (truncated to fit
/// on a UTF-8 boundary; NULL/0 to skip). Returns the byte length of the full
/// joined text, excluding the NUL; call once with `(NULL, 0)` to size, then
/// pass a `char[len + 1]`. `0` means no warnings (or a NULL handle); readers
/// that are total attach none. Each line reads `CODE: message`; split at the
/// first `": "` to recover the code.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_warnings(
    net: *const PioNetwork,
    warnbuf: *mut c_char,
    warnlen: usize,
) -> usize {
    unsafe {
        guard(0, || {
            let Some(c) = network_ref(net) else { return 0 };
            let msg = c.warnings.join("\n");
            copy_to_buf(warnbuf, warnlen, &msg);
            msg.len()
        })
    }
}

/// Free a network handle from [`pio_parse_file`], [`pio_parse_str`],
/// `pio_read_dir`, or [`pio_normalize`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_network_free(net: *mut PioNetwork) {
    unsafe {
        // Under the same panic guard as every other entry point: the drop is
        // pure deallocation today, but "catches panics" must not depend on that
        // staying true.
        guard((), || {
            if !net.is_null() {
                drop(Box::from_raw(net));
            }
        });
    }
}

unsafe fn network_ref<'a>(net: *const PioNetwork) -> Option<&'a PioNetwork> {
    unsafe { net.as_ref() }
}

/// View `net` through its cached [`IndexCore`] with no per-call rebuild.
unsafe fn view<'a>(net: *const PioNetwork) -> Option<IndexedNetwork<'a>> {
    unsafe {
        net.as_ref()
            .map(|c| IndexedNetwork::with_core(&c.net, &c.core))
    }
}

/// Solver preparation repairs for [`pio_normalize`], in the extensible options
/// struct convention this header states once. Zero the struct, set
/// `struct_size` to `sizeof(PioNormalizeOptions)`, fill what you need; NULL is
/// every default, which is the plain per unit pass with no repair.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct PioNormalizeOptions {
    /// `sizeof(PioNormalizeOptions)` as the caller's build sees it.
    pub struct_size: usize,
    /// Nonzero applies the same branch angle difference bound repair as
    /// PowerModels: `angmin <= -pi/2`, `angmax >= pi/2`, and zero/zero bounds
    /// are replaced by `[-angle_bound_pad, angle_bound_pad]`, and a repair that
    /// would invert the interval widens to that same window.
    pub clamp_angle_bounds: i32,
    /// Named so the layout carries no implicit padding. Must be zero.
    pub reserved: i32,
    /// The half width of the replacement window, in radians, which must be in
    /// `(0, pi/2)`. `0` means the default 1.0472, so a zero filled struct is
    /// every default; any other out of range value fails the call.
    pub angle_bound_pad: f64,
}

/// Read a caller's [`PioNormalizeOptions`] into the Rust `NormalizeOptions`.
///
/// # Safety
/// `opts` must be NULL or point at a `PioNormalizeOptions` whose `struct_size`
/// bytes are readable.
unsafe fn normalize_options_from_c(
    opts: *const PioNormalizeOptions,
) -> Result<NormalizeOptions, String> {
    let Some(raw) = (unsafe { options_from_c(opts, "PioNormalizeOptions") })? else {
        return Ok(NormalizeOptions::default());
    };
    if raw.reserved != 0 {
        return Err(coded(
            &codes::BIND_CAPI_INVALID_OPTIONS,
            "PioNormalizeOptions.reserved is not zero; it names the layout's padding and carries \
             no value",
        ));
    }
    // Zero is not a legal pad, so it is free to mean the default and a zero
    // filled struct is exactly the default options.
    let angle_bound_pad = if raw.angle_bound_pad == 0.0 {
        POWER_MODELS_ANGLE_BOUND_PAD
    } else {
        raw.angle_bound_pad
    };
    Ok(NormalizeOptions {
        clamp_angle_bounds: raw.clamp_angle_bounds != 0,
        angle_bound_pad,
    })
}

/// Normalize `net` into a NEW network handle: per unit, radians, out of service
/// filtered, source bus ids preserved, bus types canonicalized (see
/// `BalancedNetwork::to_normalized`). A value transform, not a serialization, hence
/// the verb, while the `to_*` family re-encodes unchanged data. The result is
/// independent of `net`; free both with [`pio_network_free`]. Every extractor
/// and serializer works on it unchanged (the handle is per unit, not MW).
///
/// `opts` turns on the solver preparation repairs; see [`PioNormalizeOptions`].
/// NULL is every default and is the plain pass. The read warnings already on
/// `net` and any repair warnings are attached to the returned handle and can be
/// read with [`pio_warnings`].
///
/// Returns `NULL` on error (no reference bus can be chosen, a non-positive base
/// MVA, or an options struct this build cannot honor) and writes the message
/// into `errbuf`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_normalize(
    net: *const PioNetwork,
    opts: *const PioNormalizeOptions,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut PioNetwork {
    unsafe {
        finish_network(errbuf, errlen, "panic while normalizing", || {
            let c = network_ref(net).ok_or_else(|| null_handle("network handle"))?;
            let options = normalize_options_from_c(opts)?;
            let out = c
                .net
                .to_normalized_with_options(&options)
                .map_err(err_line)?;
            let mut diagnostics = c.diagnostics.clone();
            diagnostics.extend(out.diagnostics);
            Ok((out.network, diagnostics))
        })
    }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_n_buses(net: *const PioNetwork) -> usize {
    // The star-lowered space, which is what every other per-bus extractor
    // reports. Through v4 this counted the unexpanded table while
    // pio_bus_demand, pio_bus_shunt and pio_n_islands counted the expansion, so
    // a caller sizing a per-bus buffer from here read short by one entry per
    // in-service 3-winding transformer.
    unsafe { guard(0, || view(net).map_or(0, |v| v.n())) }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_n_branches(net: *const PioNetwork) -> usize {
    // The star-lowered space, matching pio_n_buses: a 3-winding transformer
    // becomes a star bus plus three branches, and a caller building a matrix
    // from these tables needs both halves of that or the star bus is an
    // isolated row.
    unsafe { guard(0, || view(net).map_or(0, |v| v.branches().len())) }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_n_switches(net: *const PioNetwork) -> usize {
    unsafe { guard(0, || network_ref(net).map_or(0, |c| c.net.switches.len())) }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_n_gens(net: *const PioNetwork) -> usize {
    unsafe { guard(0, || network_ref(net).map_or(0, |c| c.net.generators.len())) }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_base_mva(net: *const PioNetwork) -> f64 {
    unsafe { guard(0.0, || network_ref(net).map_or(0.0, |c| c.net.base_mva)) }
}

/// Case name. Writes UTF-8 bytes into `out`, up to `cap`, NUL-terminates when
/// possible, and returns the byte length needed excluding the NUL. `NULL` or
/// `cap == 0` is a size query.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_network_name(
    net: *const PioNetwork,
    out: *mut c_char,
    cap: usize,
) -> usize {
    unsafe {
        guard(0, || {
            let Some(c) = network_ref(net) else { return 0 };
            copy_to_buf(out, cap, &c.net.name);
            c.net.name.len()
        })
    }
}

/// Source format token used by the JSON snapshot and accepted by every
/// `from` parameter, for example `matpower`, `powermodels-json`, or
/// `normalized`. Uses the same cap/count string convention as
/// [`pio_network_name`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_source_format(
    net: *const PioNetwork,
    out: *mut c_char,
    cap: usize,
) -> usize {
    unsafe {
        guard(0, || {
            let Some(c) = network_ref(net) else { return 0 };
            let name = c.net.source_format.name().to_owned();
            copy_to_buf(out, cap, &name);
            name.len()
        })
    }
}

/// Serialize a compact balanced network summary as JSON for display and scalar
/// queries without serializing [`pio_to_json`]'s full payload.
///
/// `counts` is the case file's own inventory, so it counts a 3-winding
/// transformer once under `transformers_3w` rather than as the star bus and
/// three branches it lowers to. `topology.n_buses` and `topology.n_branches`
/// are that lowered space, the one [`pio_n_buses`] and [`pio_branches`]
/// report and the one the rest of `topology` is computed over. The two differ
/// only for a case with an in-service 3-winding transformer.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_summary_json(
    net: *const PioNetwork,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut c_char {
    unsafe {
        finish_string(
            errbuf,
            errlen,
            "panic while serializing summary JSON",
            || {
                let c = network_ref(net).ok_or_else(|| null_handle("network handle"))?;
                let v = IndexedNetwork::with_core(&c.net, &c.core);
                let reference_bus_indices = v.reference_bus_indices();
                let reference_bus_ids: Vec<usize> = reference_bus_indices
                    .iter()
                    .map(|&idx| v.bus_id(idx).0)
                    .collect();
                let summary = serde_json::json!({
                    powerio::version::VERSION_KEY: powerio::VERSION,
                    "name": c.net.name,
                    "source_format": c.net.source_format.name(),
                    "base_mva": c.net.base_mva,
                    "base_frequency": c.net.base_frequency,
                    "counts": {
                        "buses": c.net.buses.len(),
                        "loads": c.net.loads.len(),
                        "shunts": c.net.shunts.len(),
                        "branches": c.net.branches.len(),
                        "switches": c.net.switches.len(),
                        "generators": c.net.generators.len(),
                        "storage": c.net.storage.len(),
                        "hvdc": c.net.hvdc.len(),
                        "transformers_3w": c.net.transformers_3w.len(),
                        "areas": c.net.areas.len(),
                        "warnings": c.warnings.len(),
                    },
                    "topology": {
                        "n_buses": v.n(),
                        "n_branches": v.branches().len(),
                        "reference_bus_ids": reference_bus_ids,
                        "reference_bus_indices": reference_bus_indices,
                        "n_components": v.n_connected_components(),
                        "is_radial": v.is_radial(),
                    },
                });
                serde_json::to_string(&summary)
                    .map_err(|e| coded(&codes::EMIT_CAPI_SERIALIZE_FAILED, e))
            },
        )
    }
}

/// The normalize pass's identity and provenance vectors for `net`, as owned
/// JSON. Free the returned string with [`pio_string_free`]. On error this
/// returns NULL and writes the message into `errbuf`.
///
/// The document is `{"schema", "powerio_version", "pass", "index"}`, where
/// `index` is the pass's own `SolverTableIndex`:
///
/// * `bus_ids` — source bus id of each dense bus row, including the stable id
///   a synthetic 3-winding star bus receives;
/// * `reference_bus_indices`, `component_labels`, `branch_from_arc_indices`,
///   `branch_to_arc_indices` — the index vectors the solver tables are built
///   over;
/// * `bus_source_rows`, `load_source_rows`, `shunt_source_rows`,
///   `branch_source_rows`, `switch_source_rows`, `generator_source_rows`,
///   `storage_source_rows`, `hvdc_source_rows` — the source row of each
///   normalized row, or `null` where the row has no source (a star bus and the
///   branches it lowers to).
///
/// This is the map the pass computes for itself, which is the point: a caller
/// that wants normalized tables plus provenance no longer has to re-derive the
/// drop rule from an unfiltered second extraction, and so cannot disagree with
/// the pass wherever the guess does not model what it does — three-winding star
/// lowering changing the branch count, most of all. Reaching the same vectors
/// through the Arrow solver tables needs the `arrow` feature, which is off by
/// default, and through a `.pio.json` package needs a package; this needs
/// neither.
///
/// One normalize pass runs per call and nothing is cached on the handle, so a
/// caller reading several vectors should read the document once.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_solver_index_json(
    net: *const PioNetwork,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut c_char {
    unsafe {
        finish_string(
            errbuf,
            errlen,
            "panic while serializing solver table index JSON",
            || {
                let c = network_ref(net).ok_or_else(|| null_handle("network handle"))?;
                let index = c.net.to_normalized_solver_table_index().map_err(err_line)?;
                let doc = serde_json::json!({
                    "schema": "powerio.solver_index",
                    powerio::version::VERSION_KEY: powerio::VERSION,
                    "pass": powerio::NORMALIZED_SOLVER_TABLES_PASS,
                    "index": index,
                });
                serde_json::to_string(&doc)
                    .map_err(|e| coded(&codes::EMIT_CAPI_SERIALIZE_FAILED, e))
            },
        )
    }
}

/// Dense `[0, n)` index of the single reference (slack) bus, or `-1` if not
/// exactly one. An INDEX into the [`pio_bus_ids`] ordering, not a bus id;
/// `pio_branches` from/to carry ids, so the unit is in the name. A network may
/// carry several references (one per island, or a normalized case that kept
/// the file's multiple `REF` buses); [`pio_ref_bus_indices`] reads them all,
/// and its count (`NULL` out) tells zero from many.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_ref_bus_index(net: *const PioNetwork) -> i64 {
    unsafe {
        guard(-1, || match view(net) {
            Some(v) => v
                .reference_bus_index()
                .map_or(-1, |i| i64::try_from(i).unwrap_or(-1)),
            None => -1,
        })
    }
}

/// Write the dense `[0, n)` indices of the reference (slack) buses, ascending,
/// into `out`, up to `cap` entries, and return the total count: the cap/count
/// convention of [`pio_bus_ids`]. `0` means none; `> 1` means one reference
/// per island or several fixed references in one island (a normalized case
/// always reports `>= 1`).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_ref_bus_indices(
    net: *const PioNetwork,
    out: *mut i64,
    cap: usize,
) -> usize {
    unsafe {
        guard(0, || {
            view(net).map_or(0, |v| {
                fill(
                    out,
                    cap,
                    v.reference_bus_indices()
                        .into_iter()
                        .map(|i| i64::try_from(i).unwrap_or(-1)),
                )
            })
        })
    }
}

/// Number of islands: connected components of the in-service topology.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_n_islands(net: *const PioNetwork) -> usize {
    unsafe { guard(0, || view(net).map_or(0, |v| v.n_connected_components())) }
}

/// `1` if the in-service topology is radial (every island a tree), else `0`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_is_radial(net: *const PioNetwork) -> i32 {
    unsafe { guard(0, || view(net).map_or(0, |v| i32::from(v.is_radial()))) }
}

/// `PioWriteOptions.missing_gen_cost_mode`: leave a missing cost row absent.
pub const PIO_MISSING_GEN_COST_PRESERVE: i32 = 0;
/// `PioWriteOptions.missing_gen_cost_mode`: fail when an in-service generator
/// has no cost row.
pub const PIO_MISSING_GEN_COST_REQUIRE: i32 = 1;
/// `PioWriteOptions.missing_gen_cost_mode`: synthesize a MATPOWER polynomial
/// row from the five `fill_*` fields.
pub const PIO_MISSING_GEN_COST_FILL: i32 = 2;

/// Write-time policies for the four transmission write entry points, in the
/// extensible options struct convention this header states once. Zero the
/// struct, set `struct_size` to `sizeof(PioWriteOptions)`, fill what you need;
/// NULL is every default and is what these entry points did before the
/// parameter existed.
///
/// The three `pio_dist_*` write entry points take no options struct: the
/// multiconductor writers carry their own per format options and none of them
/// is reachable from this policy set.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct PioWriteOptions {
    /// `sizeof(PioWriteOptions)` as the caller's build sees it.
    pub struct_size: usize,
    /// What to do with an in-service generator that has no active power cost
    /// row: `PIO_MISSING_GEN_COST_PRESERVE`, `_REQUIRE`, or `_FILL`.
    pub missing_gen_cost_mode: i32,
    /// Named so the layout carries no implicit padding. Must be zero.
    pub reserved: i32,
    /// The quadratic coefficient of the row `_FILL` synthesizes.
    pub fill_c2: f64,
    /// The linear coefficient of the row `_FILL` synthesizes.
    pub fill_c1: f64,
    /// The constant coefficient of the row `_FILL` synthesizes.
    pub fill_c0: f64,
    /// The startup cost `_FILL` synthesizes.
    pub fill_startup: f64,
    /// The shutdown cost `_FILL` synthesizes.
    pub fill_shutdown: f64,
    /// Generator cost patches as CSV text, never a path: a header row of
    /// `gen_index,bus,c2,c1,c0` and optional `startup,shutdown`, then one row
    /// per patched generator. A write entry point never opens a file the caller
    /// names, so read the CSV yourself and hand over its bytes. NULL applies no
    /// patches.
    pub gen_cost_csv: *const c_char,
}

/// Copy a caller's extensible options struct into a zero filled local of this
/// build's layout, or `None` when `opts` is NULL and every default applies.
///
/// The read is bounded by `min(struct_size, size_of::<T>())`, so a shorter
/// struct from an older caller reads as zeros past its end. A nonzero tail
/// beyond this build's size fails: the caller set a field this library does not
/// implement, and honoring the rest would drop that request silently.
///
/// # Safety
/// `T` must be `#[repr(C)]`, valid when all zero, and carry `usize struct_size`
/// as its first field; `opts` must be NULL or point at `struct_size` readable
/// bytes.
unsafe fn options_from_c<T: Copy>(opts: *const T, name: &str) -> Result<Option<T>, String> {
    if opts.is_null() {
        return Ok(None);
    }
    let own = size_of::<T>();
    let declared = unsafe { opts.cast::<usize>().read_unaligned() };
    if declared < size_of::<usize>() {
        return Err(coded(
            &codes::BIND_CAPI_INVALID_OPTIONS,
            format!(
                "{name}.struct_size is {declared}; set it to sizeof({name}), {own} in this build"
            ),
        ));
    }
    if declared > own {
        let tail =
            unsafe { std::slice::from_raw_parts(opts.cast::<u8>().add(own), declared - own) };
        if tail.iter().any(|b| *b != 0) {
            return Err(coded(
                &codes::BIND_CAPI_INVALID_OPTIONS,
                format!(
                    "{name}.struct_size is {declared}, past this build's {own}, and a field is \
                     set beyond it; this library cannot honor an option it does not implement"
                ),
            ));
        }
    }
    let mut out = std::mem::MaybeUninit::<T>::zeroed();
    unsafe {
        std::ptr::copy_nonoverlapping(
            opts.cast::<u8>(),
            out.as_mut_ptr().cast::<u8>(),
            declared.min(own),
        );
        Ok(Some(out.assume_init()))
    }
}

/// Read a caller's [`PioWriteOptions`] into the Rust `WriteOptions`.
///
/// # Safety
/// `opts` must be NULL or point at a `PioWriteOptions` whose `struct_size`
/// bytes are readable, and `gen_cost_csv` at a NUL terminated string.
unsafe fn write_options_from_c(opts: *const PioWriteOptions) -> Result<WriteOptions, String> {
    let Some(raw) = (unsafe { options_from_c(opts, "PioWriteOptions") })? else {
        return Ok(WriteOptions::default());
    };
    if raw.reserved != 0 {
        return Err(coded(
            &codes::BIND_CAPI_INVALID_OPTIONS,
            "PioWriteOptions.reserved is not zero; it names the layout's padding and carries no value",
        ));
    }
    let fill = [
        raw.fill_c2,
        raw.fill_c1,
        raw.fill_c0,
        raw.fill_startup,
        raw.fill_shutdown,
    ];
    let missing_gen_cost = match raw.missing_gen_cost_mode {
        PIO_MISSING_GEN_COST_PRESERVE => MissingGenCostPolicy::Preserve,
        PIO_MISSING_GEN_COST_REQUIRE => MissingGenCostPolicy::Require,
        PIO_MISSING_GEN_COST_FILL => {
            if fill.iter().any(|v| !v.is_finite()) {
                return Err(coded(
                    &codes::BIND_CAPI_INVALID_OPTIONS,
                    "PioWriteOptions fill_* values must be finite",
                ));
            }
            MissingGenCostPolicy::Fill {
                c2: raw.fill_c2,
                c1: raw.fill_c1,
                c0: raw.fill_c0,
                startup: raw.fill_startup,
                shutdown: raw.fill_shutdown,
            }
        }
        other => {
            return Err(coded(
                &codes::BIND_CAPI_INVALID_OPTIONS,
                format!(
                    "PioWriteOptions.missing_gen_cost_mode is {other}; it is 0 preserve, \
                     1 require, or 2 fill"
                ),
            ));
        }
    };
    // The five fill values are read only in fill mode. Naming a stray one beats
    // dropping a request the caller believes was honored.
    if raw.missing_gen_cost_mode != PIO_MISSING_GEN_COST_FILL && fill.iter().any(|v| *v != 0.0) {
        return Err(coded(
            &codes::BIND_CAPI_INVALID_OPTIONS,
            format!(
                "PioWriteOptions carries a fill_* value with missing_gen_cost_mode {}; \
                 those fields apply only to mode {PIO_MISSING_GEN_COST_FILL} (fill)",
                raw.missing_gen_cost_mode
            ),
        ));
    }
    let gen_cost_patches = if raw.gen_cost_csv.is_null() {
        Vec::new()
    } else {
        let text = required_cstr(raw.gen_cost_csv, "PioWriteOptions.gen_cost_csv")?;
        powerio::parse_gen_cost_csv(text).map_err(err_line)?
    };
    Ok(WriteOptions {
        missing_gen_cost,
        gen_cost_patches,
    })
}

/// Serialize `net` to the named format `to`: the one text serializer; every
/// format is named by a string. Accepts the [`pio_parse_str`] names:
/// `matpower` is a byte-exact echo when the handle was parsed from MATPOWER.
/// Model JSON is not a case format and has no token here: write it with
/// [`pio_to_json`].
///
/// `opts` carries the write-time cost policies (NULL for every default); see
/// [`PioWriteOptions`]. A non-default policy works on a copy, so the handle is
/// unchanged, and the policy's own findings lead `out_diagnostics_json`.
///
/// Returns the text as an owned C string (free with [`pio_string_free`]),
/// `NULL` on error (message into `errbuf`). The writer's findings, if any, are
/// published through `out_diagnostics_json` as one owned JSON array of
/// diagnostic records (free it with [`pio_string_free`]), or NULL when there
/// are none; a returned string has no handle to attach them to. Pass NULL to
/// discard them. `out_diagnostics_json` is written on every return path and is
/// NULL whenever this returns NULL, so an error return leaves nothing to free.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_to_format(
    net: *const PioNetwork,
    to: *const c_char,
    opts: *const PioWriteOptions,
    out_diagnostics_json: *mut *mut c_char,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut c_char {
    unsafe {
        finish_conversion(
            out_diagnostics_json,
            errbuf,
            errlen,
            "panic while converting",
            || {
                let c = network_ref(net).ok_or_else(|| null_handle("network handle"))?;
                let target = target_format_from_c(to)?;
                let options = write_options_from_c(opts)?;
                let conv = c
                    .net
                    .to_format_with_options(target, &options)
                    .map_err(err_line)?;
                Ok((conv.text, conv.diagnostics))
            },
        )
    }
}

/// Write `diagnostics` to `out_diagnostics_json` as one owned JSON array, or
/// NULL when there are none. NULL `out_diagnostics_json` discards them.
///
/// A caller buffer cannot work here. Findings are unbounded in a way an error
/// message is not: one per lossy element, so a large case produces more than
/// any fixed size a caller can guess. The errbuf idiom stays for errors, which
/// are one message.
unsafe fn set_out_diagnostics(
    out_diagnostics_json: *mut *mut c_char,
    diagnostics: &[StructuredDiagnostic],
) {
    unsafe {
        if out_diagnostics_json.is_null() {
            return;
        }
        *out_diagnostics_json = if diagnostics.is_empty() {
            std::ptr::null_mut()
        } else {
            // A serialization or interior NUL failure here would have to be
            // reported through a channel the caller reads as "nothing was
            // lost", so reporting no findings beats handing back a prefix of
            // the set as the whole of it.
            serde_json::to_string(diagnostics)
                .ok()
                .and_then(into_cstring)
                .unwrap_or(std::ptr::null_mut())
        };
    }
}

/// Finish a text entry point that publishes findings: run `f` (producing the
/// text with its findings, or an error message) under the panic guard, publish
/// the findings through `out_diagnostics_json`, and hand back the owned C
/// string, or write the error (`panic_msg` if `f` panicked) and return NULL.
/// The shared tail of [`pio_to_format`], [`pio_convert_file`],
/// [`pio_convert_str`] and [`pio_geo_parse`], mirroring [`finish_network`].
unsafe fn finish_conversion(
    out_diagnostics_json: *mut *mut c_char,
    errbuf: *mut c_char,
    errlen: usize,
    panic_msg: &str,
    f: impl FnOnce() -> Result<(String, Vec<StructuredDiagnostic>), String>,
) -> *mut c_char {
    unsafe {
        // Set before running f: a caller reads it on every return path, and a
        // stale value from an earlier call must not be mistaken for this one's.
        set_out_diagnostics(out_diagnostics_json, &[]);
        match catch_unwind(AssertUnwindSafe(f)) {
            Ok(Ok((text, diagnostics))) => {
                // Build the returned string before publishing: an interior NUL
                // in the text fails here, and a caller reading NULL as an error
                // never frees what a publish would have left behind.
                let out = finish_cstring(text, errbuf, errlen);
                if !out.is_null() {
                    set_out_diagnostics(out_diagnostics_json, &diagnostics);
                }
                out
            }
            Ok(Err(msg)) => {
                copy_to_buf(errbuf, errlen, &msg);
                std::ptr::null_mut()
            }
            Err(_) => {
                let msg = coded(&codes::BIND_CAPI_PANIC, panic_msg);
                copy_to_buf(errbuf, errlen, &msg);
                std::ptr::null_mut()
            }
        }
    }
}

/// Convert the case file at `path` from format `from` (NULL to infer from the
/// path, as [`pio_parse_file`]) to format `to`, without keeping a handle.
/// `opts` carries the write-time cost policies (NULL for every default); see
/// [`PioWriteOptions`].
/// Returns the converted text as an owned C string (free with
/// [`pio_string_free`]), `NULL` on error. The findings, read side first, are
/// published through `out_diagnostics_json` as one owned JSON array of
/// diagnostic records (free it with [`pio_string_free`]), NULL when there are
/// none. Pass NULL to discard them. `out_diagnostics_json` is written on every
/// return path and is NULL whenever this returns NULL, so an error return
/// leaves nothing to free.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_convert_file(
    path: *const c_char,
    from: *const c_char,
    to: *const c_char,
    opts: *const PioWriteOptions,
    out_diagnostics_json: *mut *mut c_char,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut c_char {
    unsafe {
        finish_conversion(
            out_diagnostics_json,
            errbuf,
            errlen,
            "panic while converting",
            || {
                let path = required_cstr(path, "path")?;
                let from = optional_cstr(from, "from")?;
                let target = target_format_from_c(to)?;
                let options = write_options_from_c(opts)?;
                let conv = powerio::convert_file_with_options(
                    std::path::Path::new(path),
                    target,
                    from,
                    &options,
                )
                .map_err(err_line)?;
                Ok((conv.text, conv.diagnostics))
            },
        )
    }
}

/// Convert in-memory case `text` from format `from` (required; there is no
/// path to infer from) to format `to` without keeping a handle. `opts` carries
/// the write-time cost policies (NULL for every default); see
/// [`PioWriteOptions`]. Returns the converted text as an owned C
/// string (free with [`pio_string_free`]), `NULL` on error. The findings, read
/// side first, are published through `out_diagnostics_json` as one owned JSON
/// array of diagnostic records (free it with [`pio_string_free`]), NULL when
/// there are none. Pass NULL to discard them. `out_diagnostics_json` is written
/// on every return path and is NULL whenever this returns NULL, so an error
/// return leaves nothing to free.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_convert_str(
    text: *const c_char,
    from: *const c_char,
    to: *const c_char,
    opts: *const PioWriteOptions,
    out_diagnostics_json: *mut *mut c_char,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut c_char {
    unsafe {
        finish_conversion(
            out_diagnostics_json,
            errbuf,
            errlen,
            "panic while converting",
            || {
                let text = required_cstr(text, "text")?;
                let from = required_cstr(from, "from")?;
                let target = target_format_from_c(to)?;
                let options = write_options_from_c(opts)?;
                let conv = powerio::convert_str_with_options(text, target, from, &options)
                    .map_err(err_line)?;
                Ok((conv.text, conv.diagnostics))
            },
        )
    }
}

/// Write `net` into `out_dir` as the named directory format `to`. PyPSA CSV
/// (`pypsa-csv`/`pypsa`) is the currently supported directory format; a text format name is
/// an error pointing back at [`pio_to_format`]. `opts` carries the write-time
/// cost policies (NULL for every default); see [`PioWriteOptions`].
/// Returns `0` on success and
/// `-1` on error (message into `errbuf`). The writer's findings, if any, are
/// published through `out_diagnostics_json` as one owned JSON array of
/// diagnostic records (free it with [`pio_string_free`]), NULL when there are
/// none. Pass NULL to discard them. `out_diagnostics_json` is written on every
/// return path and is NULL whenever this returns `-1`, so an error return
/// leaves nothing to free.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_write_dir(
    net: *const PioNetwork,
    to: *const c_char,
    out_dir: *const c_char,
    opts: *const PioWriteOptions,
    out_diagnostics_json: *mut *mut c_char,
    errbuf: *mut c_char,
    errlen: usize,
) -> i32 {
    unsafe {
        set_out_diagnostics(out_diagnostics_json, &[]);
        let r = catch_unwind(AssertUnwindSafe(|| {
            let c = network_ref(net).ok_or_else(|| null_handle("network handle"))?;
            let to = required_cstr(to, "to")?;
            let out_dir = required_cstr(out_dir, "out_dir")?;
            let options = write_options_from_c(opts)?;
            powerio::write_dir_with_options(&c.net, to, std::path::Path::new(out_dir), &options)
                .map_err(err_line)
        }));
        match r {
            Ok(Ok(warnings)) => {
                set_out_diagnostics(out_diagnostics_json, &warnings);
                0
            }
            Ok(Err(msg)) => {
                copy_to_buf(errbuf, errlen, &msg);
                -1
            }
            Err(_) => {
                let msg = coded(&codes::BIND_CAPI_PANIC, "panic while writing directory");
                copy_to_buf(errbuf, errlen, &msg);
                -1
            }
        }
    }
}

/// Free any owned C string returned by this API.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_string_free(s: *mut c_char) {
    unsafe {
        // Same rationale as `pio_network_free`: the boundary catches panics.
        guard((), || {
            if !s.is_null() {
                drop(CString::from_raw(s));
            }
        });
    }
}

/// Write up to `cap` values from `vals` into `out` and return the total number
/// available. A NULL `out` skips the write, so `(NULL, 0)` is the pure count
/// query of the cap/count convention every array extractor shares.
unsafe fn fill<T: Copy>(out: *mut T, cap: usize, vals: impl ExactSizeIterator<Item = T>) -> usize {
    unsafe {
        let total = vals.len();
        if !out.is_null() {
            for (i, v) in vals.take(cap).enumerate() {
                *out.add(i) = v;
            }
        }
        total
    }
}

/// Write the 1-based external bus ids, in dense order, into `out`, up to `cap`
/// entries, and return the total bus count. This ordering DEFINES the dense
/// index space every other per-bus array shares. Call once with `(NULL, 0)` to
/// size, allocate, then call again to fill. Ids are int64 in `1..2^63-1` (a v4
/// invariant): a reader whose source ids are strings assigns dense ids and
/// keeps the source name, and a numeric id past that range is refused at the
/// read boundary rather than passed through.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_bus_ids(net: *const PioNetwork, out: *mut i64, cap: usize) -> usize {
    unsafe {
        guard(0, || {
            // The star-lowered space, so every per-bus column keyed to this
            // ordering has an id at every index. A star bus carries the
            // synthesized id the expansion assigned it, and the read boundary
            // reserves the headroom for it, so the conversion cannot fail.
            view(net).map_or(0, |v| {
                fill(
                    out,
                    cap,
                    (0..v.n()).map(|i| i64::try_from(v.bus_id(i).0).unwrap_or(-1)),
                )
            })
        })
    }
}

/// Write the branch table as parallel arrays, each up to `cap` entries, and
/// return the total branch count. A branch is any two-terminal series element
/// lines and transformers alike (a transformer has `tap != 0`). `from`/`to`
/// are 1-based bus IDS (the [`pio_bus_ids`] id space, not dense indices); map
/// them to dense matrix rows with the [`pio_bus_ids`] ordering. Any output
/// pointer may be NULL to skip that column; all NULL is the count query.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_branches(
    net: *const PioNetwork,
    from: *mut i64,
    to: *mut i64,
    r: *mut f64,
    x: *mut f64,
    b: *mut f64,
    tap: *mut f64,
    shift: *mut f64,
    in_service: *mut u8,
    cap: usize,
) -> usize {
    unsafe {
        guard(0, || {
            let Some(v) = view(net) else { return 0 };
            let branches = v.branches();
            fill(
                from,
                cap,
                branches
                    .iter()
                    .map(|br| i64::try_from(br.from.0).unwrap_or(-1)),
            );
            fill(
                to,
                cap,
                branches
                    .iter()
                    .map(|br| i64::try_from(br.to.0).unwrap_or(-1)),
            );
            fill(r, cap, branches.iter().map(|br| br.r));
            fill(x, cap, branches.iter().map(|br| br.x));
            fill(b, cap, branches.iter().map(|br| br.total_charging_b()));
            fill(tap, cap, branches.iter().map(|br| br.tap));
            fill(shift, cap, branches.iter().map(|br| br.shift));
            fill(
                in_service,
                cap,
                branches.iter().map(|br| u8::from(br.in_service)),
            );
            branches.len()
        })
    }
}

/// Write the branch terminal charging table as parallel arrays, each up to
/// `cap` entries, and return the total branch count. Columns are p.u.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_branch_charging(
    net: *const PioNetwork,
    g_fr: *mut f64,
    b_fr: *mut f64,
    g_to: *mut f64,
    b_to: *mut f64,
    cap: usize,
) -> usize {
    unsafe {
        guard(0, || {
            let Some(v) = view(net) else { return 0 };
            let branches = v.branches();
            fill(
                g_fr,
                cap,
                branches.iter().map(|br| br.terminal_charging().g_fr),
            );
            fill(
                b_fr,
                cap,
                branches.iter().map(|br| br.terminal_charging().b_fr),
            );
            fill(
                g_to,
                cap,
                branches.iter().map(|br| br.terminal_charging().g_to),
            );
            fill(
                b_to,
                cap,
                branches.iter().map(|br| br.terminal_charging().b_to),
            );
            branches.len()
        })
    }
}

/// Write the switch table as parallel arrays, each up to `cap` entries, and
/// return the total switch count. `from`/`to` are external bus ids.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_switches(
    net: *const PioNetwork,
    from: *mut i64,
    to: *mut i64,
    closed: *mut u8,
    thermal_rating: *mut f64,
    current_rating: *mut f64,
    pf: *mut f64,
    qf: *mut f64,
    pt: *mut f64,
    qt: *mut f64,
    cap: usize,
) -> usize {
    unsafe {
        guard(0, || {
            let Some(c) = network_ref(net) else { return 0 };
            let net = &c.net;
            fill(
                from,
                cap,
                net.switches
                    .iter()
                    .map(|sw| i64::try_from(sw.from.0).unwrap_or(-1)),
            );
            fill(
                to,
                cap,
                net.switches
                    .iter()
                    .map(|sw| i64::try_from(sw.to.0).unwrap_or(-1)),
            );
            fill(
                closed,
                cap,
                net.switches.iter().map(|sw| u8::from(sw.closed)),
            );
            fill(
                thermal_rating,
                cap,
                net.switches
                    .iter()
                    .map(|sw| sw.thermal_rating.unwrap_or(0.0)),
            );
            fill(
                current_rating,
                cap,
                net.switches
                    .iter()
                    .map(|sw| sw.current_rating.unwrap_or(0.0)),
            );
            fill(pf, cap, net.switches.iter().map(|sw| sw.pf.unwrap_or(0.0)));
            fill(qf, cap, net.switches.iter().map(|sw| sw.qf.unwrap_or(0.0)));
            fill(pt, cap, net.switches.iter().map(|sw| sw.pt.unwrap_or(0.0)));
            fill(qt, cap, net.switches.iter().map(|sw| sw.qt.unwrap_or(0.0)));
            net.switches.len()
        })
    }
}

/// Write the generator table as parallel arrays, each up to `cap` entries, and
/// return the total generator count. `bus` is the 1-based bus id (the
/// [`pio_bus_ids`] id space). Any output pointer may be NULL to skip.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_gens(
    net: *const PioNetwork,
    bus: *mut i64,
    pg: *mut f64,
    pmax: *mut f64,
    pmin: *mut f64,
    in_service: *mut u8,
    cap: usize,
) -> usize {
    unsafe {
        guard(0, || {
            let Some(c) = network_ref(net) else { return 0 };
            let net = &c.net;
            fill(
                bus,
                cap,
                net.generators
                    .iter()
                    .map(|g| i64::try_from(g.bus.0).unwrap_or(-1)),
            );
            fill(pg, cap, net.generators.iter().map(|g| g.pg));
            fill(pmax, cap, net.generators.iter().map(|g| g.pmax));
            fill(pmin, cap, net.generators.iter().map(|g| g.pmin));
            fill(
                in_service,
                cap,
                net.generators.iter().map(|g| u8::from(g.in_service)),
            );
            net.generators.len()
        })
    }
}

/// Write the per-bus demand aggregates (active `pd`, reactive `qd`, summed
/// over each bus's loads, dense [`pio_bus_ids`] order), each up to `cap`
/// entries, and return the total bus count. Either pointer may be NULL.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_bus_demand(
    net: *const PioNetwork,
    pd: *mut f64,
    qd: *mut f64,
    cap: usize,
) -> usize {
    unsafe {
        guard(0, || {
            view(net).map_or(0, |v| {
                // Return an explicit bus count, not the last fill's result, so the
                // cap/count return is independent of which columns were requested.
                let n = fill(pd, cap, v.pd().iter().copied());
                fill(qd, cap, v.qd().iter().copied());
                n
            })
        })
    }
}

/// Write the per-bus shunt aggregates (conductance `gs`, susceptance `bs`,
/// dense [`pio_bus_ids`] order), each up to `cap` entries, and return the
/// total bus count. Either pointer may be NULL.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_bus_shunt(
    net: *const PioNetwork,
    gs: *mut f64,
    bs: *mut f64,
    cap: usize,
) -> usize {
    unsafe {
        guard(0, || {
            view(net).map_or(0, |v| {
                // Explicit bus count, not the last fill's result (see pio_bus_demand).
                let n = fill(gs, cap, v.gs().iter().copied());
                fill(bs, cap, v.bs().iter().copied());
                n
            })
        })
    }
}

// ---------------------------------------------------------------------------
// DC incidence parts (`matrix` feature). The signed incidence `A` crosses the
// boundary as `PIO_ARROW_TABLE_INCIDENCE`; the per-branch and per-bus vectors
// it is assembled with did not cross at all. A differentiable-modeling
// consumer treats the susceptance as a parameter vector — its positive DC
// Laplacian is `L = A diag(b ⊙ sw) Aᵀ`, rebuilt as `b` and the switching
// `sw` move — so an
// assembled `B'` has already summed away the thing being differentiated and
// cannot serve it at any granularity. Reimplementing `x/(r² + x²)` outside
// inherits none of the guards 0.9 put on this path (#292): the magnitude bound
// on the denominator, `NonFiniteSusceptance` instead of a silently zero weight
// edge, `DegenerateTap` under `Matpower`. These carry the vectors and the
// guards together.
// ---------------------------------------------------------------------------

/// Resolve a C convention token. The tokens Python's `convention=` keyword and
/// the CLI's `--convention` accept, case and separator insensitive.
///
/// [`powerio::DcConvention`]'s `FromStr` owns the token set and the refusals,
/// so "the tokens Python accepts" is a shared parser rather than a second copy
/// of the match arms that could drift from it. NULL is the only spelling of
/// "unset" here: an empty string is a token the caller passed, and resolving
/// it to the default would be this ABI silently choosing a convention.
#[cfg(feature = "matrix")]
fn dc_convention_from_c(convention: *const c_char) -> Result<powerio_matrix::DcConvention, String> {
    let Some(raw) = optional_cstr(convention, "convention")? else {
        // NULL is the default, as it is for every other optional C argument.
        return Ok(powerio_matrix::DcConvention::default());
    };
    raw.parse::<powerio_matrix::DcConvention>()
        .map_err(|message| coded(&codes::BIND_CAPI_INVALID_OPTIONS, message))
}

/// Build the incidence parts of `net` under `convention`, or the guard's own
/// refusal.
#[cfg(feature = "matrix")]
unsafe fn incidence_parts_of(
    net: *const PioNetwork,
    convention: *const c_char,
) -> Result<powerio_matrix::IncidenceParts, String> {
    let conv = dc_convention_from_c(convention)?;
    let v = unsafe { view(net) }.ok_or_else(|| null_handle("network handle"))?;
    powerio_matrix::build_incidence(&v, conv, &powerio_matrix::BuildOptions::default())
        .map_err(err_line)
}

/// Narrow a branch table row to the `int64` the vectors carry. `-1` is this
/// family's whole-call refusal, so a row that cannot be represented is
/// reported as one rather than written into the array as a value a consumer
/// would read back as a row number.
#[cfg(feature = "matrix")]
fn branch_row_as_i64(row: usize) -> Result<i64, String> {
    i64::try_from(row).map_err(|_| {
        coded(
            &codes::BIND_CAPI_INDEX_OUT_OF_RANGE,
            format!("branch row {row} does not fit in int64"),
        )
    })
}

/// Run `f`, write `vals` into `out` under the cap/count convention, and return
/// the total. `-1` on a refusal or a panic, with the message in `errbuf`,
/// because the guard's refusal is the value here and a plain `0` return would
/// throw it away.
///
/// [`finish_string`]'s counterpart for the array extractors, and like it, not
/// any one feature's helper: the DC extractors and [`pio_scenario_ids`] share
/// the shape, so it is built whenever either of their features is.
#[cfg(any(feature = "matrix", feature = "gridfm"))]
unsafe fn finish_fill<T: Copy>(
    errbuf: *mut c_char,
    errlen: usize,
    panic_msg: &str,
    out: *mut T,
    cap: usize,
    f: impl FnOnce() -> Result<Vec<T>, String>,
) -> isize {
    unsafe {
        match catch_unwind(AssertUnwindSafe(f)) {
            Ok(Ok(vals)) => {
                let Ok(total) = isize::try_from(vals.len()) else {
                    let msg = coded(&codes::BIND_CAPI_INDEX_OUT_OF_RANGE, "count exceeds isize");
                    copy_to_buf(errbuf, errlen, &msg);
                    return -1;
                };
                fill(out, cap, vals.iter().copied());
                total
            }
            Ok(Err(msg)) => {
                copy_to_buf(errbuf, errlen, &msg);
                -1
            }
            Err(_) => {
                copy_to_buf(errbuf, errlen, &coded(&codes::BIND_CAPI_PANIC, panic_msg));
                -1
            }
        }
    }
}

/// Write the per-branch DC susceptance under `convention` into `out`, up to
/// `cap` entries, and return `m`, the number of incidence columns. Call once
/// with `(NULL, 0)` to size, allocate, then call again to fill.
///
/// `convention` takes the tokens Python and the CLI accept — `"series"`
/// (`b = x/(r² + x²)`, the default and what NULL selects), `"matpower"`
/// (`b = 1/(x τ)`), `"reactance-only"` (`b = 1/x`) — case and separator
/// insensitive. `b` is a **positive** Laplacian edge weight, as
/// `DcConvention::branch_susceptance` states; PowerModels and tellegen write
/// the negation, so a consumer negates once knowingly.
///
/// Column order is [`pio_incidence_branch_rows`]'s, which is in-service branch
/// order with the skipped and self-loop rows removed — not `pio_branches`
/// order, and `m` is not `pio_n_branches`. Read both to line the vector up
/// with the case.
///
/// Returns `-1` and writes the message into `errbuf` on a refusal: a
/// non-finite susceptance is `NonFiniteSusceptance` and a `Matpower` tap too
/// small to divide by is `DegenerateTap`, which is the point of asking rather
/// than recomputing `x/(r² + x²)` outside.
///
/// One incidence build runs per call and nothing is cached on the handle, so
/// the size query and the fill are two builds, and each of the four
/// extractors pays its own. A consumer that wants several of these vectors
/// should size once, keep the count, and hold what it reads.
///
/// The size query is skippable outright, which is the cheaper half of that
/// advice: `m <= pio_n_branches` always, so a caller that allocates
/// [`pio_n_branches`] entries can fill in one call and take the return as the
/// real count. Every extractor in this family has such a bound and states it,
/// and paying a few unused entries per vector is what buys back the second
/// build.
#[cfg(feature = "matrix")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_branch_susceptance(
    net: *const PioNetwork,
    convention: *const c_char,
    out: *mut f64,
    cap: usize,
    errbuf: *mut c_char,
    errlen: usize,
) -> isize {
    unsafe {
        finish_fill(
            errbuf,
            errlen,
            "panic while building branch susceptances",
            out,
            cap,
            || Ok(incidence_parts_of(net, convention)?.b),
        )
    }
}

/// Write the per-bus phase shift injection under `convention` into `out`, up
/// to `cap` entries, and return `n`, the bus count. The dense order is
/// [`pio_bus_ids`]'s, the one every per-bus array shares.
///
/// This is MATPOWER `makeBdc`'s `Pbusinj`, the constant term of
/// `L θ = C_g p_g − (p_d + g_s + p_shift)`. All zeros under
/// `"reactance-only"`, which carries no shifts, and under any convention for a
/// case with no phase shifter — a caller that skips it silently drops the
/// shifter's contribution instead.
///
/// `convention`, the per-call incidence build, and the `-1` refusal are
/// [`pio_branch_susceptance`]'s. The bound is exact here — `n` is
/// [`pio_n_buses`], the same `n` every per-bus array carries — so a caller
/// that allocates it never needs the `(NULL, 0)` query at all.
#[cfg(feature = "matrix")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_phase_shift_injection(
    net: *const PioNetwork,
    convention: *const c_char,
    out: *mut f64,
    cap: usize,
    errbuf: *mut c_char,
    errlen: usize,
) -> isize {
    unsafe {
        finish_fill(
            errbuf,
            errlen,
            "panic while building the phase shift injection",
            out,
            cap,
            || Ok(incidence_parts_of(net, convention)?.p_shift),
        )
    }
}

/// Write the source branch row of each incidence column into `out`, up to
/// `cap` entries, and return `m`. This is `branch_of_col`: the map from a
/// position in [`pio_branch_susceptance`]'s vector back to a row of the case's
/// branch table, and the only way to line either vector up with the case.
///
/// Rows are the [`pio_branches`] index space. A self-loop and a branch the DC
/// denominator guard skipped have no column, so this is not the identity and
/// `m <= pio_n_branches`.
///
/// `convention`, the per-call incidence build, and the `-1` refusal are
/// [`pio_branch_susceptance`]'s, and so is the bound: a [`pio_n_branches`]
/// buffer fills in one call.
#[cfg(feature = "matrix")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_incidence_branch_rows(
    net: *const PioNetwork,
    convention: *const c_char,
    out: *mut i64,
    cap: usize,
    errbuf: *mut c_char,
    errlen: usize,
) -> isize {
    unsafe {
        finish_fill(
            errbuf,
            errlen,
            "panic while building the incidence column map",
            out,
            cap,
            || {
                let rows = incidence_parts_of(net, convention)?.branch_of_col;
                rows.into_iter().map(branch_row_as_i64).collect()
            },
        )
    }
}

/// Write the source rows of the in-service branches the DC denominator guard
/// skipped into `out`, up to `cap` entries, and return the count.
///
/// A consumer that rebuilds `B` from `A` and `b` needs these: the branches are
/// in the case and in `pio_branches`, and they are in no incidence column, so
/// without them its matrix and the library's disagree with nothing to say why.
/// A case with none returns `0`, which is the ordinary answer.
///
/// `convention`, the per-call incidence build, and the `-1` refusal are
/// [`pio_branch_susceptance`]'s. These rows are a subset of the branch table,
/// so [`pio_n_branches`] bounds them too and the same one-call fill applies —
/// on the ordinary case that skips nothing, the buffer goes entirely unused
/// and the build is still saved.
#[cfg(feature = "matrix")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_incidence_skipped_rows(
    net: *const PioNetwork,
    convention: *const c_char,
    out: *mut i64,
    cap: usize,
    errbuf: *mut c_char,
    errlen: usize,
) -> isize {
    unsafe {
        finish_fill(
            errbuf,
            errlen,
            "panic while building the skipped branch rows",
            out,
            cap,
            || {
                let parts = incidence_parts_of(net, convention)?;
                parts
                    .skipped_zero_impedance
                    .branch_indices
                    .into_iter()
                    .map(branch_row_as_i64)
                    .collect()
            },
        )
    }
}

/// Export one network table over the Arrow C Data Interface: the `to_`
/// conversion whose output type is Arrow structs rather than a string, and the
/// bulk table surface of this ABI. Tables 0..5 are raw network tables; tables
/// 6..14 are normalized solver tables with per unit/radian values and dense
/// zero based row ids; tables 15..18 carry COO triplets in that dense index
/// space with dimensions in schema metadata; tables 19 and 20 are the axis maps
/// naming what each row and column of those triplets is (`matrix_bus` carries
/// the bus id, source row, reference flag and island per index, `matrix_branch`
/// the source row and endpoint ids). Tables 21 and 22 carry normalized
/// generator cost: one header row per solver generator, in `solver_gen` order,
/// slicing `[coeff_offset, coeff_offset + coeff_count)` of the flattened
/// coefficient table. `model` 2 reads position `i` of a `coeff_count` long
/// slice as the coefficient of `p^(coeff_count - 1 - i)`; `model` 1 reads even
/// positions as per unit active power at a breakpoint and odd positions as the
/// curve value there; `model` 0 means the generator carries no cost row, and
/// its `coeff_offset` is `-1`. Every table entry in
/// [`pio_arrow_catalog_json`] states which of the three it is under `format`.
/// New columns extend the Arrow schema without changing an existing C
/// signature.
///
/// `table` is one of the `PIO_ARROW_TABLE_*` selectors. Raw table columns use
/// EXTERNAL bus ids (the `pio_bus_ids` id space), not the gridfm schema. On
/// success (returns `0`),
/// `out_array` and `out_schema` are populated with owned C Data Interface
/// structs: ownership of the Arrow buffers transfers to the caller, both
/// `release` callbacks are non-NULL, and the caller MUST invoke each exactly
/// once when done (skipping one leaks; the structs outlive `pio_network_free`).
/// On error (returns `-1`) the message is written into `errbuf` and the
/// out-params are left untouched. Only built with the `arrow` cargo feature.
#[cfg(feature = "arrow")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_to_arrow(
    net: *const PioNetwork,
    table: i32,
    out_array: *mut arrow::ffi::FFI_ArrowArray,
    out_schema: *mut arrow::ffi::FFI_ArrowSchema,
    errbuf: *mut c_char,
    errlen: usize,
) -> i32 {
    unsafe {
        let r = catch_unwind(AssertUnwindSafe(|| {
            if out_array.is_null() || out_schema.is_null() {
                return Err(coded(
                    &codes::BIND_CAPI_NULL_ARGUMENT,
                    "out_array or out_schema is NULL",
                ));
            }
            let c = network_ref(net).ok_or_else(|| null_handle("network handle"))?;
            arrow_export::export(&c.net, &c.core, table)
        }));
        match r {
            Ok(Ok((array, schema))) => {
                // Move the FFI structs into caller memory: ptr::write does not
                // drop the (caller-zeroed) destination and does not run Drop on
                // `array`/`schema`, so the producer release callbacks transfer to
                // the caller. Exactly one owner.
                std::ptr::write(out_array, array);
                std::ptr::write(out_schema, schema);
                0
            }
            Ok(Err(msg)) => {
                copy_to_buf(errbuf, errlen, &msg);
                -1
            }
            Err(_) => {
                let msg = coded(&codes::BIND_CAPI_PANIC, "panic while exporting Arrow");
                copy_to_buf(errbuf, errlen, &msg);
                -1
            }
        }
    }
}

/// Return the Arrow table catalog as owned compact JSON.
///
/// The catalog is feature based rather than handle based: it describes what
/// this library build can export, not what a particular network contains. Top
/// level fields are `powerio_version`, `producer`, and `tables`. Each table
/// entry includes `id`, `name`, `format`, `feature_requirements`, `available`,
/// `row_axis`, `col_axis`, `units`, and `columns`. Each column entry includes
/// `name`, `type`, and `nullable`. Through v4 both levels carried a
/// `schema_version`; one release version now covers every document powerio
/// authors, so the top level names it and the per-table copy is gone.
///
/// Free the returned string with [`pio_string_free`]. On error this returns
/// NULL and writes the message into `errbuf`. Only built with the `arrow` cargo
/// feature.
#[cfg(feature = "arrow")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_arrow_catalog_json(errbuf: *mut c_char, errlen: usize) -> *mut c_char {
    unsafe {
        finish_string(errbuf, errlen, "panic while building Arrow catalog", || {
            Ok(arrow_export::catalog_json())
        })
    }
}

// ---------------------------------------------------------------------------
// Package API (`pkg` feature). `.pio.json` compiler packages sit above the
// balanced and multiconductor handles: a package wraps exactly one payload and
// carries provenance, validation, diagnostics, and lowering history.
// ---------------------------------------------------------------------------

/// Opaque `.pio.json` compiler package handle. A package owns one
/// [`powerio_pkg::NetworkPackage`], which wraps either a balanced
/// [`PioNetwork`] payload or a multiconductor [`PioDistNetwork`] payload.
#[cfg(feature = "pkg")]
pub struct PioPackage {
    package: powerio_pkg::NetworkPackage,
}

#[cfg(feature = "pkg")]
const _: fn() = || {
    fn assert_send_sync<T: Send + Sync>() {}
    assert_send_sync::<PioPackage>();
};

#[cfg(feature = "pkg")]
fn lowering_options(base_mva: f64) -> powerio_pkg::MulticonductorToBalancedOptions {
    powerio_pkg::MulticonductorToBalancedOptions {
        base_mva,
        ..Default::default()
    }
}

#[cfg(feature = "pkg")]
unsafe fn finish_package(
    errbuf: *mut c_char,
    errlen: usize,
    panic_msg: &str,
    f: impl FnOnce() -> Result<powerio_pkg::NetworkPackage, String>,
) -> *mut PioPackage {
    unsafe {
        match catch_unwind(AssertUnwindSafe(f)) {
            Ok(Ok(package)) => Box::into_raw(Box::new(PioPackage { package })),
            Ok(Err(msg)) => {
                copy_to_buf(errbuf, errlen, &msg);
                std::ptr::null_mut()
            }
            Err(_) => {
                copy_to_buf(errbuf, errlen, &coded(&codes::BIND_CAPI_PANIC, panic_msg));
                std::ptr::null_mut()
            }
        }
    }
}

/// Parse a `.pio.json` package file into an opaque package handle. This reads
/// only the package; case format names still enter through
/// [`pio_parse_file`] / [`pio_dist_parse_file`] and package constructors.
/// Returns `NULL` on error and writes the message into `errbuf`. Free the handle
/// with [`pio_package_free`].
#[cfg(feature = "pkg")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_package_parse_file(
    path: *const c_char,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut PioPackage {
    unsafe {
        finish_package(errbuf, errlen, "panic while parsing package", || {
            let path = required_cstr(path, "path")?;
            let text =
                std::fs::read_to_string(path).map_err(|e| coded(&codes::READ_CAPI_IO_FAILED, e))?;
            powerio_pkg::NetworkPackage::from_json(&text).map_err(err_line)
        })
    }
}

/// Parse in-memory `.pio.json` text into an opaque package handle. Returns
/// `NULL` on error and writes the message into `errbuf`. Free the handle with
/// [`pio_package_free`].
#[cfg(feature = "pkg")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_package_parse_str(
    text: *const c_char,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut PioPackage {
    unsafe {
        finish_package(errbuf, errlen, "panic while parsing package", || {
            let text = required_cstr(text, "text")?;
            powerio_pkg::NetworkPackage::from_json(text).map_err(err_line)
        })
    }
}

/// Free a package handle returned by `pio_package_*`. NULL is a no-op; free
/// exactly once.
#[cfg(feature = "pkg")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_package_free(pkg: *mut PioPackage) {
    unsafe {
        guard((), || {
            if !pkg.is_null() {
                drop(Box::from_raw(pkg));
            }
        });
    }
}

/// Finish a `*mut c_char` package accessor: run `f` on the non-NULL handle
/// under the panic guard and hand back an owned C string, or write the error
/// (`panic_msg` if `f` panicked) into `errbuf` and return NULL. The shared
/// tail of the `pio_package_*_json` getters.
#[cfg(feature = "pkg")]
unsafe fn finish_package_json(
    pkg: *const PioPackage,
    errbuf: *mut c_char,
    errlen: usize,
    panic_msg: &str,
    f: impl FnOnce(&PioPackage) -> Result<String, String>,
) -> *mut c_char {
    unsafe {
        finish_string(errbuf, errlen, panic_msg, || {
            let pkg = pkg.as_ref().ok_or_else(|| null_handle("package handle"))?;
            f(pkg)
        })
    }
}

/// Serialize a package handle to compact `.pio.json`. Returns an owned C string
/// (free with [`pio_string_free`]) or `NULL` on error.
#[cfg(feature = "pkg")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_package_to_json(
    pkg: *const PioPackage,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut c_char {
    unsafe {
        finish_package_json(
            pkg,
            errbuf,
            errlen,
            "panic while serializing package",
            |p| p.package.to_json().map_err(err_line),
        )
    }
}

/// Wrap a balanced [`PioNetwork`] handle in a `.pio.json` package. A
/// `PioNetwork` carries a `powerio::BalancedNetwork`.
/// `include_solver_metadata != 0` attaches compact normalized solver table
/// metadata.
#[cfg(feature = "pkg")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_package_from_balanced_network(
    net: *const PioNetwork,
    include_solver_metadata: i32,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut PioPackage {
    unsafe {
        finish_package(
            errbuf,
            errlen,
            "panic while packaging balanced network",
            || {
                let net = network_ref(net).ok_or_else(|| null_handle("network handle"))?;
                let mut package = powerio_pkg::NetworkPackage::from_balanced_with_read_diagnostics(
                    net.net.clone(),
                    net.diagnostics.clone(),
                );
                if include_solver_metadata != 0 {
                    package
                        .attach_normalized_solver_table_metadata()
                        .map_err(err_line)?;
                }
                Ok(package)
            },
        )
    }
}

/// Wrap a multiconductor [`PioDistNetwork`] handle in a `.pio.json` package. A
/// `PioDistNetwork` carries a `powerio_dist::MulticonductorNetwork`.
#[cfg(all(feature = "pkg", feature = "dist"))]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_package_from_multiconductor_network(
    net: *const PioDistNetwork,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut PioPackage {
    unsafe {
        finish_package(
            errbuf,
            errlen,
            "panic while packaging multiconductor network",
            || {
                let net = net
                    .as_ref()
                    .ok_or_else(|| null_handle("distribution network handle"))?;
                Ok(powerio_pkg::NetworkPackage::from_multiconductor(
                    net.net.clone(),
                ))
            },
        )
    }
}

/// Materialize the balanced payload of a package handle as an owned network
/// handle: the inverse of [`pio_package_from_balanced_network`]. Errors when
/// the package holds a different model kind. The handle is built from the
/// payload alone: it retains no source text, so a same format write is a fresh
/// serialization rather than a byte-exact echo, and it carries no parse
/// warnings. Free with [`pio_network_free`].
#[cfg(feature = "pkg")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_package_to_balanced_network(
    pkg: *const PioPackage,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut PioNetwork {
    unsafe {
        finish_network(
            errbuf,
            errlen,
            "panic while extracting balanced network",
            || {
                let pkg = pkg.as_ref().ok_or_else(|| null_handle("package handle"))?;
                let net = pkg.package.model.as_balanced().ok_or_else(|| {
                    let message = if cfg!(feature = "dist") {
                        "package holds a multiconductor model where balanced was asked for; use \
                         pio_package_to_multiconductor_network"
                    } else {
                        "package holds a multiconductor model where balanced was asked for; \
                         extracting it needs a build with the `dist` feature \
                         (pio_package_to_multiconductor_network)"
                    };
                    coded(&pkg_codes::REQUEST_PACKAGE_WRONG_MODEL_KIND, message)
                })?;
                let mut net = net.clone();
                // An in-memory package still holds the payload's #[serde(skip)]
                // source text; drop it so extraction behaves the same whether
                // or not the package crossed JSON, and a same-format write is
                // the promised fresh serialization.
                net.source = None;
                Ok((net, Vec::new()))
            },
        )
    }
}

/// Materialize the multiconductor payload of a package handle as an owned
/// distribution network handle: the inverse of
/// [`pio_package_from_multiconductor_network`]. Errors when the package holds
/// a different model kind. The handle retains no source text, so a
/// same format write is a fresh serialization. The handle retains the payload's
/// parse warnings, readable through [`pio_dist_warnings`]. Free with
/// [`pio_dist_network_free`].
#[cfg(all(feature = "pkg", feature = "dist"))]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_package_to_multiconductor_network(
    pkg: *const PioPackage,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut PioDistNetwork {
    unsafe {
        finish_handle(
            errbuf,
            errlen,
            "panic while extracting multiconductor network",
            || {
                let pkg = pkg.as_ref().ok_or_else(|| null_handle("package handle"))?;
                let net = pkg.package.model.as_multiconductor().ok_or_else(|| {
                    coded(
                        &pkg_codes::REQUEST_PACKAGE_WRONG_MODEL_KIND,
                        "package holds a balanced model where multiconductor was asked for; use \
                         pio_package_to_balanced_network",
                    )
                })?;
                let mut net = net.clone();
                // Same in-memory strip as the balanced inverse: source and the
                // defaulted provenance are #[serde(skip)], so dropping them
                // here matches what a JSON crossing produces.
                net.source = None;
                net.defaulted = Default::default();
                Ok(PioDistNetwork { net })
            },
        )
    }
}

/// Run the package semantic validation profile in place. Returns `0` on
/// success, `-1` on error.
///
/// Unlike the read-only accessors, this rewrites the handle's `diagnostics` and
/// `validation` (the payload is untouched), so it takes the handle non-`const`
/// and needs exclusive access: no other call may touch the same handle
/// concurrently. [`pio_package_set_operating_points`] is the other such
/// entry point; every other call takes the handle `const` and shares it.
#[cfg(feature = "pkg")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_package_validate(
    pkg: *mut PioPackage,
    errbuf: *mut c_char,
    errlen: usize,
) -> i32 {
    unsafe {
        let result = catch_unwind(AssertUnwindSafe(|| {
            let pkg = pkg.as_mut().ok_or_else(|| null_handle("package handle"))?;
            pkg.package.run_sane_validation();
            Ok::<_, String>(())
        }));
        match result {
            Ok(Ok(())) => 0,
            Ok(Err(msg)) => {
                copy_to_buf(errbuf, errlen, &msg);
                -1
            }
            Err(_) => {
                let msg = coded(&codes::BIND_CAPI_PANIC, "panic while validating package");
                copy_to_buf(errbuf, errlen, &msg);
                -1
            }
        }
    }
}

/// Return the package validation summary as JSON. The returned string is owned
/// by the library; free it with [`pio_string_free`].
#[cfg(feature = "pkg")]
#[unsafe(no_mangle)]
pub unsafe extern "C" fn pio_package_validation_json(
    pkg: *const PioPackage,
    errbuf: *mut c_char,
    errlen: usize,
) -> *mut c_char {
    unsafe {
        finish_package_json(
            pkg,
            errbuf,
            errlen,
            "panic while reading package validation",
            |p| {
                serde_json::to_string(&p.package.validation)
                    .map_err(|e| coded(&codes::EMIT_CAPI_SERIALIZE_FAILED, e))
            },
        )
    }
}

