/// Parse SCOPF source text into an owned problem instance. `from` currently
/// accepts `"goc3-json"`. Returns `NULL` on error and writes the message into
/// `errbuf`. Free the handle with `pio_scopf_instance_free`.
#[cfg(feature = "prob")]
#[unsafe(no_mangle)]
