            assert!(!cs.is_null(), "parse_str returned null");
            let cn = pio_normalize(cs, std::ptr::null(), err.as_mut_ptr(), err.len());
            assert!(!cn.is_null(), "normalize returned null");

            let mut ids = vec![0i64; pio_n_buses(cn)];
