    /// A zero filled `PioNormalizeOptions` with `struct_size` set, which is what
    /// a caller writes and is defined to equal a NULL `opts`.
    fn normalize_opts() -> PioNormalizeOptions {
        PioNormalizeOptions {
            struct_size: size_of::<PioNormalizeOptions>(),
            clamp_angle_bounds: 0,
            reserved: 0,
            angle_bound_pad: 0.0,
        }
    }

    /// `pio_normalize` with the given options, returning the handle or the
    /// errbuf.
    unsafe fn normalize_with(
        net: *const PioNetwork,
        opts: *const PioNormalizeOptions,
    ) -> Result<*mut PioNetwork, String> {
        let mut err = [0 as c_char; PIO_ERRBUF_MIN];
        unsafe {
            let cn = pio_normalize(net, opts, err.as_mut_ptr(), err.len());
            if cn.is_null() {
                return Err(CStr::from_ptr(err.as_ptr()).to_str().unwrap().to_owned());
            }
            Ok(cn)
        }
    }

    /// The normalized handle's model JSON, freeing the handle.
    unsafe fn normalized_json(
        net: *const PioNetwork,
        opts: *const PioNormalizeOptions,
    ) -> Result<serde_json::Value, String> {
        unsafe {
            let cn = normalize_with(net, opts)?;
            let v = network_json(cn);
            pio_network_free(cn);
            Ok(v)
        }
    }

    #[test]
    fn normalize_options_clamp_angle_bounds_and_warn() {
        let c = angle_bounds_case();
        let mut err = [0 as c_char; PIO_ERRBUF_MIN];
        unsafe {
            let mut opts = normalize_opts();
            opts.clamp_angle_bounds = 1;
            opts.angle_bound_pad = POWER_MODELS_ANGLE_BOUND_PAD;
            let cn = pio_normalize(c, &opts, err.as_mut_ptr(), err.len());
            assert!(
                !cn.is_null(),
                "normalize with options returned null: {}",
                CStr::from_ptr(err.as_ptr()).to_str().unwrap()
            );
            let v = network_json(cn);
            close(
                v["branches"][0]["angmin"].as_f64().unwrap(),
                -POWER_MODELS_ANGLE_BOUND_PAD,
            );
            close(
                v["branches"][0]["angmax"].as_f64().unwrap(),
                POWER_MODELS_ANGLE_BOUND_PAD,
            );
            close(
                v["branches"][1]["angmin"].as_f64().unwrap(),
                -POWER_MODELS_ANGLE_BOUND_PAD,
            );
            close(
                v["branches"][1]["angmax"].as_f64().unwrap(),
                POWER_MODELS_ANGLE_BOUND_PAD,
            );
            close(
                v["branches"][2]["angmin"].as_f64().unwrap(),
                -std::f64::consts::PI / 6.0,
            );
            close(
                v["branches"][2]["angmax"].as_f64().unwrap(),
                std::f64::consts::PI / 6.0,
            );
            close(
                v["branches"][3]["angmin"].as_f64().unwrap(),
                -POWER_MODELS_ANGLE_BOUND_PAD,
            );
            close(
                v["branches"][3]["angmax"].as_f64().unwrap(),
                POWER_MODELS_ANGLE_BOUND_PAD,
            );
            close(
                v["branches"][4]["angmin"].as_f64().unwrap(),
                -POWER_MODELS_ANGLE_BOUND_PAD,
            );
            close(
                v["branches"][4]["angmax"].as_f64().unwrap(),
                POWER_MODELS_ANGLE_BOUND_PAD,
            );
            for branch in v["branches"].as_array().unwrap() {
                assert!(branch["angmin"].as_f64().unwrap() <= branch["angmax"].as_f64().unwrap());
            }

            let warnings = warning_text(cn);
            assert!(warnings.contains("branch 0 angle difference bounds clamped"));
            assert!(warnings.contains("branch 1 angle difference bounds clamped"));
            assert!(warnings.contains("branch 3 angle difference bounds clamped"));
            assert!(warnings.contains("branch 4 angle difference bounds clamped"));

            pio_network_free(cn);
            pio_network_free(c);
        }
    }

